function SANDWICH_VERDICT(n, q, t, code_size):
    left  <- code_size * BALL_VOLUME(n, q, t)
    mid   <- q^n
    right <- code_size * BALL_VOLUME(n, q, 2t)
    holds <- (left <= mid) and (mid <= right)
    return holds, { |C|*V(t)=left, q^n=mid, |C|*V(2t)=right,
                    lower_estimate = mid / BALL_VOLUME(n,q,2t),
                    upper_estimate = mid / BALL_VOLUME(n,q,t) }

function GREEDY_MAXIMAL_CODE(n, q, d):
    code <- empty list
    for w in all words of length n over {0,...,q-1} (fixed order):
        if for all c in code: HAMMING(w, c) >= d:
            append w to code
    return code   # d-separated and maximal

